soup = BeautifulSoup(html, 'html.parser')

bid_table = soup.find_all('table')[0]
ask_table = soup.find_all('table')[1]

bids = []
for row in bid_table.find_all('tr')[1:]:
    volume = row.find_all('td')[0].text.strip()
    price = row.find_all('td')[1].text.strip()

    volume = volume.replace('k', '000')  # Convert 'k' to actual numbers
    volume = int(volume)
    price = int(price)
    
    bids.append((price, volume))

print("Bids:")
for price, volume in bids:
    print(f"Price: {price}, Volume: {volume}")

asks = []
for row in ask_table.find_all('tr')[1:]:
    price = row.find_all('td')[0].text.strip()
    volume = row.find_all('td')[1].text.strip()
    
    volume = volume.replace('k', '000')  # Convert 'k' to actual numbers
    volume = int(volume)
    price = int(price)
    
    asks.append((price, volume))

print("\nAsks:")
for price, volume in asks:
    print(f"Price: {price}, Volume: {volume}")